const content=window.DJ_CONTENT||{};
const menu=document.querySelector('.menu-toggle');
const nav=document.querySelector('#main-nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.querySelector('span').textContent='＋'}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.querySelector('span').textContent=open?'−':'＋'});
nav.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
function element(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text)el.textContent=text;return el}
function safeUrl(value){try{const url=new URL(value,location.href);return ['http:','https:','file:'].includes(url.protocol)?url.href:null}catch{return null}}
function photoImage(photo,lazy=true){const img=element('img');const src=safeUrl(photo.src);if(src)img.src=src;img.alt=photo.alt||'DJ KRISHLWN';img.loading=lazy?'lazy':'eager';img.decoding='async';if(photo.position)img.style.objectPosition=photo.position;return img}
if(content.hero?.src){const host=document.querySelector('#hero-visual');host.replaceChildren(photoImage(content.hero,false));host.removeAttribute('aria-hidden');document.querySelector('.hero').classList.add('has-photo')}
if(content.portrait?.src)document.querySelector('#portrait').append(photoImage(content.portrait));
if(content.biography){document.querySelector('#biography').textContent=content.biography;document.querySelector('#bio-secondary').remove()}
const dialog=document.querySelector('#lightbox');
if(content.gallery?.length){const grid=element('div','gallery-grid');content.gallery.forEach((photo,index)=>{const figure=element('figure','photo-card');const button=element('button');button.type='button';button.setAttribute('aria-label',`Ampliar fotografía ${index+1}: ${photo.alt||'DJ KRISHLWN'}`);button.append(photoImage(photo));button.addEventListener('click',()=>{const img=dialog.querySelector('img');img.src=safeUrl(photo.src)||'';img.alt=photo.alt||'DJ KRISHLWN';dialog.querySelector('p').textContent=photo.caption||'';dialog.showModal()});figure.append(button);if(photo.caption)figure.append(element('figcaption','',photo.caption));grid.append(figure)});document.querySelector('#gallery-content').replaceChildren(grid)}
dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
if(content.music?.length){const host=document.querySelector('#music-content');host.replaceChildren();content.music.forEach(track=>{const url=safeUrl(track.url);if(!url)return;const link=element('a','music-item');link.href=url;link.target='_blank';link.rel='noopener noreferrer';const text=element('span');text.append(element('small','eyebrow',track.type||'MÚSICA'),element('span','',track.title));link.append(text,element('span','','↗'));host.append(link)})}
const events=(content.events||[]).filter(event=>/^\d{4}-\d{2}-\d{2}$/.test(event.date)).sort((a,b)=>a.date.localeCompare(b.date));
if(events.length){const host=document.querySelector('#events-content');host.replaceChildren();events.forEach(event=>{const row=element('article','event-row');const time=element('time','',new Intl.DateTimeFormat('es',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(event.date+'T12:00:00Z')));time.dateTime=event.date;const text=element('div');text.append(element('h3','',event.title),element('p','',event.venue));row.append(time,text);host.append(row)})}
const wave=document.querySelector('.waveform');if(wave){for(let i=0;i<51;i++){const bar=element('i');bar.style.setProperty('--height',`${15+Math.abs(Math.sin(i*1.7)*Math.cos(i*.26))*65}px`);wave.append(bar)}}
if('IntersectionObserver'in window){const active=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){document.querySelectorAll('#main-nav a').forEach(a=>{if(a.hash==='#'+entry.target.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -65% 0px',threshold:0});document.querySelectorAll('main>section').forEach(section=>active.observe(section));if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');reveal.unobserve(entry.target)}}),{threshold:.06});document.querySelectorAll('.about-layout,.section-heading,.music-layout,.event-empty,.contact h2').forEach(el=>{el.classList.add('reveal');reveal.observe(el)})}}
// La navegación cambia de contraste según la portada visible.
const header=document.querySelector('.header');
if('IntersectionObserver'in window){new IntersectionObserver(entries=>{header.classList.toggle('on-home',entries[0].isIntersecting)},{rootMargin:'-1px 0px -95% 0px'}).observe(document.querySelector('#home'))}
if(content.hero?.cutout)document.querySelector('.hero').classList.add('has-cutout');
